mapper.select:
SELECT u.user_id AS userId, la.login_id AS loginId, t.tenant_code AS tenantCode, u.user_nm AS userNm, u.email_addr AS emailAddr, COALESCE(d.department_nm, '') AS departmentNm, COALESCE(string_agg(DISTINCT r.role_code, ',' ORDER BY r.role_code), '') AS roleCodesText, CASE WHEN COALESCE(u.use_at, 'N') = 'Y' AND COALESCE(la.use_at, 'N') = 'Y' THEN TRUE ELSE FALSE END AS active, la.login_code AS loginCode, COALESCE(u.use_at, 'N') AS useAt, COALESCE(la.use_at, 'N') AS loginUseAt FROM tb_user u JOIN tb_login_account la ON la.login_id = u.login_id JOIN tb_tenant t ON t.tenant_id = u.tenant_id LEFT JOIN tb_department d ON d.department_id = u.department_id LEFT JOIN tb_login_account_role lar ON lar.login_id = la.login_id LEFT JOIN tb_role r ON r.role_id = lar.role_id WHERE 1 = 1
AND t.tenant_code = #{tenantCode}
GROUP BY u.user_id, la.login_id, t.tenant_code, u.user_nm, u.email_addr, d.department_nm, u.use_at, la.use_at, la.login_code, u.created_at ORDER BY u.created_at DESC, u.user_id DESC

SELECT department_id
FROM tb_department
WHERE tenant_id = #{tenantId}
  AND department_nm = #{departmentNm}
ORDER BY department_id
LIMIT 1

SELECT login_id
FROM tb_user
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
LIMIT 1

SELECT login_id
FROM tb_login_account
WHERE tenant_id = #{tenantId}
    AND login_code = #{loginCode}
LIMIT 1

SELECT user_id
FROM tb_user
WHERE tenant_id = #{tenantId}
    AND login_id = #{loginId}
LIMIT 1

SELECT role_id
FROM tb_role
WHERE tenant_id = #{tenantId}
  AND role_code = #{roleCode}
LIMIT 1

choose.otherwise:
UPDATE tb_user
SET use_at = #{useAt},
    updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
